// Improve existing receipts in place, preserving IDs and avoiding duplicate money.
export function applyTrailUpdates(edgeList,verified){
  if(!verified.has('trail-vpac-q2'))return;
  for(const [id,date,transaction] of [['p25','2026-05-08','SA11A.777395'],['p26','2026-05-12','SA11A.781358'],['p27','2026-06-08','SA11A.819100'],['p28','2026-05-01','SA11A.764240']]){
    const edge=edgeList.find(e=>e.id===id);
    if(edge)Object.assign(edge,{label:edge.label.replace('Reported ',''),evidence:'Original SA11AI itemized receipt verifies the donor, amount and transaction date.',sourceIds:['trail-vpac-q2'],period:date,status:'documented',transactionDate:date,fecTransactionId:transaction,locator:`FEC 1993682, ${transaction}`,unit:'USD super-PAC contribution',context:'Receipt by V-PAC, separate from Ramaswamy’s candidate committee. Existing amount retained; this source upgrade creates no second contribution.',timeline:{date:day(date,'Transaction date'),lane:'campaign',moneyKind:'contribution'}});
  }
}
export function trailRelease(verified,baseNodeIds){
  const existing=new Set(baseNodeIds),nodes=trailNodes.filter(n=>!existing.has(n.id)&&n.sourceIds.every(id=>verified.has(id))).map(n=>({...n}));
  const ids=new Set([...existing,...nodes.map(n=>n.id)]);
  const edges=trailEdges.filter(e=>e.sourceIds.every(id=>verified.has(id))&&ids.has(e.source)&&ids.has(e.target));
  return {nodes,edges,complete:trailSources.every(s=>verified.has(s.id))};
}
